/**
 * Calls to the contract-workflow and admin-management database functions.
 *
 * TEMPORARY LOCAL TYPES: src/integrations/supabase/types.ts is generated by Lovable and does
 * not know the new tables/functions until the migration (docs/database/contract-approval-workflow.sql)
 * is applied and the types are regenerated. Until then this module goes through an untyped
 * view of the client and declares the shapes itself. After regeneration, switch `db` back to
 * `supabase` and replace these types with Tables<"..."> (see the plan, step E7).
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";
import { bangkokTimestamp, type ContractForm, type ContractStatus } from "@/lib/contract-workflow";

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- see the note above
const db = supabase as unknown as SupabaseClient<any>;

